      "content": "{\n  \"name\": \"coderdd\",\n  \"version\": \"1.1.0\",\n  \"description\": \"RDD (Requirement-Driven Development) AI workflow installer — install skills into .rdd/ as single source of truth and link AI client directories to it\",\n  \"keywords\": [\n    \"rdd\",\n    \"requirement-driven-development\",\n    \"ai-workflow\",\n    \"skills\",\n    \"opencode\",\n    \"claude-code\",\n    \"installer\"\n  ],\n  \"author\": \"YaphetHayate\",\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/YaphetHayate/codeRDD.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/YaphetHayate/codeRDD/issues\"\n  },\n  \"homepage\": \"https://github.com/YaphetHayate/codeRDD#readme\",\n  \"bin\": {\n    \"coderdd\": \"./bin/coderdd.js\",\n    \"coderrdd\": \"./bin/coderdd.js\"\n  },\n  \"files\": [\n    \"bin/\",\n    \"dist/cli/\",\n    \"dist/core/\",\n    \"rdd-engine/\",\n    \"rdd-pm/\",\n    \"rdd-cto/\",\n    \"rdd-ux/\",\n    \"rdd-dev/\",\n    \"rdd-qa/\",\n    \"rdd-eval/\",\n    \"rdd-pse/\",\n    \"rdd-auditor/\",\n    \"docs/code-quality.md\",\n    \".opencode/agent/rdd-explore.md\",\n    \".opencode/package.json\",\n    \".claude/agents/rdd-explore.md\",\n    \".zcode/agents/rdd-explore.md\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.json\",\n    \"build:local\": \"node scripts/build-local.mjs\",\n    \"prepare\": \"npm run build\",\n    \"prepublishOnly\": \"npm run build && node scripts/prepublish-check.js\",\n    \"register\": \"node scripts/register.js\",\n    \"unregister\": \"npm unlink -g coderdd\"\n  },\n  \"dependencies\": {\n    \"@inquirer/prompts\": \"^7.2.0\",\n    \"commander\": \"^12.1.0\"\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^26.2.0\",\n    \"typescript\": \"^5.6.0\"\n  },\n  \"engines\": {\n    \"node\": \">=18\"\n  }\n}\n"
